import { test, expect } from 'bun:test';
import { addMonths } from '../src/dates.js';
const iso = (d) => d.toISOString();
test('adds months', () => {
  expect(iso(addMonths(new Date('2024-03-15T10:30:00Z'), 1))).toBe('2024-04-15T10:30:00.000Z');
  expect(iso(addMonths(new Date('2024-11-10T00:00:00Z'), 3))).toBe('2025-02-10T00:00:00.000Z');
});
test('negative months go back', () => expect(iso(addMonths(new Date('2024-01-20T08:00:00Z'), -2))).toBe('2023-11-20T08:00:00.000Z'));
test('does not change its input', () => {
  const d = new Date('2024-05-05T00:00:00Z');
  addMonths(d, 4);
  expect(iso(d)).toBe('2024-05-05T00:00:00.000Z');
});

