import { test, expect } from 'bun:test';
import { addMonths } from '../src/dates.js';
const iso = (s, n) => addMonths(new Date(s), n).toISOString();
test('month end clamps to the last day of the target month', () => {
  expect(iso('2023-01-31T09:00:00Z', 1)).toBe('2023-02-28T09:00:00.000Z');
  expect(iso('2024-01-31T09:00:00Z', 1)).toBe('2024-02-29T09:00:00.000Z');
  expect(iso('2024-05-31T00:00:00Z', 1)).toBe('2024-06-30T00:00:00.000Z');
});
test('clamping also holds going back, across years and for long jumps', () => {
  expect(iso('2024-03-31T12:00:00Z', -1)).toBe('2024-02-29T12:00:00.000Z');
  expect(iso('2024-08-31T00:00:00Z', 6)).toBe('2025-02-28T00:00:00.000Z');
  expect(iso('2024-01-31T00:00:00Z', 13)).toBe('2025-02-28T00:00:00.000Z');
  expect(iso('2024-02-29T00:00:00Z', 12)).toBe('2025-02-28T00:00:00.000Z');
});
